/**
 * Music cultures — the Explore page's curated journeys and culture row,
 * generated by scripts/build-cultures.mjs (rules and sources live in
 * scripts/lib/cultures.mjs). Everything here is an EAR CLEF PICK drawn
 * from content the site already ships, and the page says so.
 */
import data from './cultures.json'

export interface CultureSource {
  label: string
  url: string
}

export interface CultureTrack {
  artist: string
  title: string
  /** Chart note or context from the snapshot, e.g. "Hot 100 #1, 1967". */
  note?: string
  /** A video the site already verified for this exact song, or absent. */
  videoId?: string
  /** Which verified source the video came from. */
  source?: 'chart' | 'songs-about' | 'on-this-day'
  /** The verified video is a live version, not the record. */
  live?: boolean
}

/** A "What was playing" era: a documented place + era + sound. */
export interface EraJourney {
  id: string
  kind: 'era'
  code: string
  place: string
  from: number
  to: number
  /** The era's name, e.g. "Jovem Guarda and the festival era". */
  title: string
  /** charted = a national chart archive; documented = scene history. */
  basisKind: 'charted' | 'documented'
  basis: string
  summary: string
  sources: CultureSource[]
  tracks: CultureTrack[]
  playable: number
  thumb: string | null
}

/** A "Songs about this place" list — its songs load on demand. */
export interface SongPlace {
  id: string
  kind: 'songs'
  code: string
  place: string
  placeKind: 'country' | 'us-state' | 'uk-nation' | 'city'
  count: number
  firstYear: number | null
  lastYear: number | null
  thumb: string
}

export type Culture = EraJourney | SongPlace

interface CulturesFile {
  eras: EraJourney[]
  songs: SongPlace[]
}

const file = data as unknown as CulturesFile

export const ERA_JOURNEYS: EraJourney[] = file.eras
export const SONG_PLACES: SongPlace[] = file.songs

/**
 * Journeys that can open the panel playing: at least two picks with a
 * verified video. The daily featured journey comes from these, so the
 * panel's player always has something real to play.
 */
export const MIN_FEATURED_PLAYABLE = 2

export function eraSpan(culture: { from: number; to: number }): string {
  return culture.from === culture.to
    ? `${culture.from}`
    : `${culture.from}–${culture.to}`
}

/** The year the globe moves to for an era: its middle. */
export function eraYear(culture: { from: number; to: number }): number {
  return Math.floor((culture.from + culture.to) / 2)
}

/**
 * The culture row's order: era journeys oldest first, with a "Songs
 * about" place after every second era so both kinds stay in view.
 * Song places in the row are the largest country-level lists.
 */
export function cultureRow(
  eras: EraJourney[],
  songs: SongPlace[],
  songSlots = 8,
): Culture[] {
  const sortedEras = [...eras].sort((a, b) => a.from - b.from || a.to - b.to)
  const songPicks = songs
    .filter((place) => place.placeKind === 'country' && place.count >= 5)
    .slice(0, songSlots)
  const row: Culture[] = []
  let songAt = 0
  sortedEras.forEach((era, index) => {
    row.push(era)
    if (index % 2 === 1 && songAt < songPicks.length) {
      row.push(songPicks[songAt++])
    }
  })
  return [...row, ...songPicks.slice(songAt)]
}
